from pathlib import Path
p=Path('/home/ubuntu/tonan-study/client/src/pages/Home.tsx')
s=p.read_text()
start=s.index('function CalendarGrid')
end=s.index('\nfunction PersonalSchedule', start)
new=r'''function CalendarGrid({ sessions, events, onSelect }: { sessions: { createdAt: Date }[]; events: { eventDate: string; title: string }[]; onSelect: (date: string) => void }) {
  const days = daysInCurrentMonth();
  const sessionDays = new Set(sessions.map(item => format(new Date(item.createdAt), "yyyy-MM-dd")));
  const today = new Date();
  return <div><div className="mb-3 flex items-center justify-between"><div><p className="font-semibold">{format(today, "yyyy年 M月", { locale: ja })}</p><p className="text-xs text-muted-foreground">学習した日は草が育ちます。日付をタップすると詳細を確認できます。</p></div><Leaf className="h-5 w-5 text-emerald-500" /></div><div className="grid grid-cols-7 gap-1 text-center text-[10px] text-muted-foreground">{["日", "月", "火", "水", "木", "金", "土"].map(day => <span key={day}>{day}</span>)}</div><div className="mt-1 grid grid-cols-7 gap-1">{days.map((date, index) => { if (!date) return <div key={`blank-${index}`} />; const key = format(date, "yyyy-MM-dd"); const learned = sessionDays.has(key); const event = events.find(item => item.eventDate === key); return <button type="button" key={key} onClick={() => onSelect(key)} className={cn("relative flex aspect-square flex-col items-center justify-center rounded-xl text-xs transition active:scale-95", isSameDay(date, today) ? "ring-2 ring-primary/60" : "", learned ? "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300" : "bg-muted/55")}>{learned ? <Sprout className="h-4 w-4" /> : <span>{date.getDate()}</span>}{event && <span className="absolute bottom-1 h-1 w-1 rounded-full bg-amber-500" title={event.title} />}</button>; })}</div></div>;
}

function CalendarGardenPager({ pin, category, sessions, events }: { pin: string; category: Category; sessions: { createdAt: Date }[]; events: { eventDate: string; title: string }[] }) {
  const [page, setPage] = useState<"calendar" | "garden">("calendar");
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const touchStart = useRef<number | null>(null);
  const utils = trpc.useUtils();
  const detail = trpc.learning.dayDetail.useQuery({ pin, category, date: selectedDate ?? "1970-01-01" }, { enabled: Boolean(selectedDate) });
  const removeEvent = trpc.learning.deletePersonalEvent.useMutation({ onSuccess: async () => { toast.success("予定を削除しました"); await utils.learning.dashboard.invalidate(); await utils.learning.dayDetail.invalidate(); }, onError: error => toast.error(error.message) });
  const onSwipeEnd = (clientX: number) => { if (touchStart.current === null) return; const difference = clientX - touchStart.current; if (Math.abs(difference) > 45) setPage(difference < 0 ? "garden" : "calendar"); touchStart.current = null; };
  return <><div className="space-y-2"><div className="overflow-hidden rounded-2xl"><motion.div className="flex w-[200%]" animate={{ x: page === "calendar" ? "0%" : "-50%" }} transition={{ duration: 0.26, ease: [0.23, 1, 0.32, 1] }} onTouchStart={event => { touchStart.current = event.touches[0]?.clientX ?? null; }} onTouchEnd={event => onSwipeEnd(event.changedTouches[0]?.clientX ?? 0)}><div className="w-1/2 pr-1"><Card><CardContent className="p-4"><CalendarGrid sessions={sessions} events={events} onSelect={setSelectedDate} /></CardContent></Card></div><div className="w-1/2 pl-1"><Card className="h-full min-h-72 border-dashed border-emerald-500/45 bg-emerald-50/45 dark:bg-emerald-950/20"><CardContent className="flex h-full min-h-72 flex-col items-center justify-center p-6 text-center"><div className="flex h-16 w-16 items-center justify-center rounded-2xl border border-dashed border-emerald-500/50 bg-background/60"><Sprout className="h-7 w-7 text-emerald-600" /></div><Badge variant="outline" className="mt-4 border-emerald-500/40 text-emerald-700 dark:text-emerald-300">後日実装</Badge><p className="mt-2 font-semibold">モンスター育成エリア</p><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">学習時間・習得単語・連続学習と連動する育成機能のための専用スペースです。</p></CardContent></Card></div></motion.div></div><div className="flex items-center justify-center gap-2"><button type="button" aria-label="カレンダーを表示" onClick={() => setPage("calendar")} className={cn("h-1.5 rounded-full transition-all", page === "calendar" ? "w-6 bg-primary" : "w-1.5 bg-muted-foreground/35")} /><button type="button" aria-label="モンスター育成エリアを表示" onClick={() => setPage("garden")} className={cn("h-1.5 rounded-full transition-all", page === "garden" ? "w-6 bg-primary" : "w-1.5 bg-muted-foreground/35")} /></div><p className="text-center text-[11px] text-muted-foreground">横にスワイプして {page === "calendar" ? "モンスター育成エリア" : "カレンダー"} を表示</p></div>{selectedDate && <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 flex items-end justify-center bg-black/40 p-3 sm:items-center"><Card className="max-h-[80vh] w-full max-w-md overflow-y-auto"><CardHeader className="flex flex-row items-start justify-between gap-3"><div><CardTitle>{format(new Date(`${selectedDate}T00:00:00`), "M月d日（E）", { locale: ja })}</CardTitle><CardDescription>その日の学習記録とマイ予定</CardDescription></div><Button size="icon" variant="ghost" onClick={() => setSelectedDate(null)} aria-label="閉じる"><X className="h-4 w-4" /></Button></CardHeader><CardContent className="space-y-3">{detail.isLoading ? <p className="py-4 text-center text-sm text-muted-foreground">読み込み中…</p> : detail.data ? <><div className="grid grid-cols-3 gap-2"><div className="rounded-xl bg-muted/60 p-3 text-center"><p className="text-lg font-bold">{formatDuration(detail.data.totalSeconds)}</p><p className="text-[10px] text-muted-foreground">学習時間</p></div><div className="rounded-xl bg-muted/60 p-3 text-center"><p className="text-lg font-bold">{detail.data.learned}</p><p className="text-[10px] text-muted-foreground">覚えた数</p></div><div className="rounded-xl bg-muted/60 p-3 text-center"><p className="text-lg font-bold">{detail.data.retention}%</p><p className="text-[10px] text-muted-foreground">定着率</p></div></div><div className="space-y-2">{detail.data.events.length ? detail.data.events.map((event: { id: number; title: string; eventDate: string }) => <div key={event.id} className="flex items-center gap-2 rounded-xl bg-amber-50 p-3 dark:bg-amber-950/25"><span className="min-w-0 flex-1 text-sm">{event.title}</span><Button size="sm" variant="outline" onClick={() => removeEvent.mutate({ pin, eventId: event.id })}>予定を削除</Button></div>) : <p className="rounded-xl border border-dashed p-3 text-center text-sm text-muted-foreground">この日のマイ予定はありません。</p>}</div></> : <p className="text-sm text-muted-foreground">詳細を取得できませんでした。</p>}</CardContent></Card></div>}</>;
}'''
s=s[:start]+new+s[end:]
s=s.replace('<CalendarGardenPager sessions={data.sessions} events={[...data.events, ...(data.personalEvents ?? [])]} />','<CalendarGardenPager pin={pin} category={category} sessions={data.sessions} events={[...data.events, ...(data.personalEvents ?? [])]} />')
old='const create = trpc.learning.createCardSet.useMutation({ onSuccess: async () => { toast.success("単語カードを保存しました"); await utils.learning.cardSets.invalidate(); setSetName(""); }, onError: error => toast.error(error.message) });'
newmut=old+'\n  const deleteSet = trpc.learning.deleteCardSet.useMutation({ onSuccess: async () => { toast.success("単語カードを削除しました"); await utils.learning.cardSets.invalidate(); await utils.learning.dashboard.invalidate(); }, onError: error => toast.error(error.message) });'
s=s.replace(old,newmut,1)
oldmap='data.cardSets.map((item: { id: number; name: string; bookId: number; startNo: number; endNo: number }) => <button key={item.id} className="flex w-full items-center justify-between rounded-2xl border bg-card p-4 text-left transition hover:border-primary/40" onClick={() => setActiveSet(item)}><div><p className="font-semibold">{item.name}</p><p className="mt-1 text-xs text-muted-foreground">No. {item.startNo} 〜 {item.endNo}</p></div><ChevronRight className="h-5 w-5 text-muted-foreground" /></button>)'
newmap='data.cardSets.map((item: { id: number; name: string; bookId: number; startNo: number; endNo: number }) => <div key={item.id} className="flex items-center gap-2 rounded-2xl border bg-card p-2 transition hover:border-primary/40"><button className="min-w-0 flex-1 p-2 text-left" onClick={() => setActiveSet(item)}><p className="font-semibold">{item.name}</p><p className="mt-1 text-xs text-muted-foreground">No. {item.startNo} 〜 {item.endNo}</p></button><Button size="sm" variant="ghost" onClick={() => { if (window.confirm("この単語カードを削除しますか？")) deleteSet.mutate({ pin, cardSetId: item.id }); }}>削除</Button><ChevronRight className="mr-2 h-5 w-5 text-muted-foreground" /></div>)'
s=s.replace(oldmap,newmap,1)
p.write_text(s)
